<script setup lang="ts">import {ref} from 'vue';import CommentEditor from '../common/CommentEditor.vue';import ApprovalActionBar from '../common/ApprovalActionBar.vue';import TimelineSteps from '../common/TimelineSteps.vue';import EntityTabs from '../common/EntityTabs.vue';import FileAttachmentList from '../common/FileAttachmentList.vue';const props=defineProps<{approval:Record<string,unknown>}>();const emit=defineEmits<{approve:[comment:string];reject:[comment:string]}>();const comment=ref('');const activeTab=ref('overview');</script>
<template><div class="approval-detail"><h3>{{props.approval.title}}</h3><EntityTabs :tabs="[{key:'overview',label:'概览'},{key:'attachments',label:'附件'}]" :active="activeTab" @change="activeTab=$event"/><template v-if="activeTab==='overview'"><p>申请人：{{props.approval.applicantName||'—'}}　客户：{{props.approval.customer||'—'}}</p><dl class="detail-list"><dt>审批类型</dt><dd>{{props.approval.type||'—'}}</dd><dt>当前状态</dt><dd>{{props.approval.status||'—'}}</dd><dt>创建时间</dt><dd>{{props.approval.createdAt||'—'}}</dd></dl><h4>审批流程</h4><TimelineSteps :steps="['提交申请','部门审批','完成']" :active="props.approval.status==='待审批'?0:props.approval.status==='已通过'?2:1"/><CommentEditor placeholder="请输入审批意见" @submit="comment=$event"/><ApprovalActionBar @approve="emit('approve',comment)" @reject="emit('reject',comment)"/></template><FileAttachmentList v-else :files="(props.approval.attachments as Array<{name:string;url?:string;size?:string}>)"/></div></template>
